css:
.ccta-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ccta-root,.ccta-root *,.ccta-root *::before,.ccta-root *::after{box-sizing:border-box}
.ccta-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ccta-root img{display:block;border:0;max-width:none}
.ccta-root > [data-node-id]{will-change:transform}
.ccta-root [hidden]{display:none!important}
.ccta-root [data-sh-theme="dark"]{display:none!important}
.ccta-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.ccta-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.ccta-root .n427_1556{grid-column:1;align-content:stretch;display:flex;gap:20px;align-items:center;line-height:normal;margin-left:0;margin-top:195px;padding-top:10px;padding-bottom:10px;position:relative;grid-row:1;width:100%}
.ccta-root .n427_1556::after{content:"";position:absolute;inset:0;border:1px solid var(--wa-point, #d4e6f5);border-radius:inherit;border-width:0 0 1px 0;pointer-events:none}
.ccta-root .n427_1557{position:relative;flex-shrink:0;font-size:18px;width:135px}
.ccta-root .n427_1558{position:relative;flex-shrink:0;font-size:16px;white-space:nowrap}
.ccta-root [data-node-id="427:1289"],.ccta-root [data-node-id="427:1317"]{height:auto!important}
.ccta-root [data-node-id="427:1537"]{width:100%!important}
.ccta-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.ccta-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.ccta-root > [data-node-id="427:1536"]{width:1010px!important;height:861px!important}
.ccta-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.ccta-root[data-theme="dark"] > [data-node-id]{background:linear-gradient(180deg,var(--wa-bg, #111720) 0%,var(--wa-bg, #0b0e13) 100%)!important}
.ccta-root[data-theme="dark"] [data-name="3D Scene"] img{filter:brightness(.88) saturate(.95) contrast(1.04)}
.ccta-root[data-theme="dark"] [data-name="Diagram Title Patch"]{background:linear-gradient(90deg,var(--wa-point, #3d2f63) 0%,var(--wa-point, #1b2a38) 50%,var(--wa-point, #352c5d) 100%)!important;border-color:var(--wa-point, #7d7bf0)!important}
.ccta-root[data-theme="dark"] [data-name="Diagram Title Patch"] p{color:var(--wa-text, #eef0fb)!important}
.ccta-root[data-theme="dark"] [data-name="Side Rail"] > [data-name="Body"]{background:linear-gradient(180deg,var(--wa-surface, #151920) 47%,color-mix(in srgb, var(--wa-surface, rgb(21 25 32)) 90%, transparent) 100%)!important;border-right-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 6%, transparent)!important}
.ccta-root[data-theme="dark"] [data-name^="Panel/"]:not([data-name="Panel/File Open"]),.ccta-root[data-theme="dark"] [data-name="Popup/Detail"]{box-shadow:inset 1px 0 0 rgba(255,255,255,.04),0 12px 30px rgba(0,0,0,.35)}
.ccta-root[data-theme="dark"] [data-name="Icon Button"]{box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.ccta-root[data-theme="dark"] .n427_1556::after{border-color:var(--wa-line, #2a3340)}
